"""#167: `mods install` skips every app-generated file under `.claude-plugin/types/` (the folder, not three names),
and its refusal line names each refused file with its install mtime and the repository's last commit time.

Temp folders only: the repo and the install are built under tmp_path, never the owner's checkout.
"""

import importlib
import os
import subprocess
from datetime import datetime

import pytest

mods = importlib.import_module("tools.agentops.mods")


def _git(repo, *a, capture=False):
    r = subprocess.run(["git", "-c", "user.name=t", "-c", "user.email=t@t", *a], cwd=repo, check=True,
                       capture_output=True, text=True)
    return r.stdout.strip() if capture else None


def _iso(ts):
    return datetime.fromtimestamp(ts).astimezone().isoformat(timespec="seconds")


@pytest.fixture
def env(tmp_path, monkeypatch):
    repo, inst = tmp_path / "repo", tmp_path / "inst"
    for root in (repo / "mods" / "unslop", inst / "unslop"):
        (root / "hooks").mkdir(parents=True)
        (root / "hooks" / "register.tsx").write_bytes(b"line1\r\nline2\n")
        (root / "DESIGN.md").write_bytes(b"design")
    _git(repo, "init", "-q")
    _git(repo, "add", "-A")
    _git(repo, "commit", "-qm", "import")
    monkeypatch.setenv("AGENTOPS_MODS_REPO", str(repo))
    monkeypatch.setenv("AGENTOPS_MODS_DIR", str(inst))
    monkeypatch.setattr(mods, "default_settings_path", lambda: tmp_path / "user_settings.json")
    return repo, inst / "unslop"


def _commit_in_repo(repo, rel, data):
    p = repo / "mods" / "unslop" / rel
    p.parent.mkdir(parents=True, exist_ok=True)
    p.write_bytes(data)
    _git(repo, "add", "-A")
    _git(repo, "commit", "-qm", "types " + data.decode())


def test_types_folder_file_newer_than_commit_is_not_refused(env, capsys):
    """Row 2: a differing `.claude-plugin/types/foo-bar/index.d.ts`, newer than the last commit -> no refusal,
    and the install's bytes are not overwritten (the app regenerated them)."""
    repo, inst = env
    rel = ".claude-plugin/types/foo-bar/index.d.ts"
    _commit_in_repo(repo, rel, b"types v1")
    (inst / rel).parent.mkdir(parents=True)
    (inst / rel).write_bytes(b"types v2 regenerated by the app")  # mtime now, after the commit
    assert mods.run_install("unslop") == 0
    assert "refused" not in capsys.readouterr().out
    assert (inst / rel).read_bytes() == b"types v2 regenerated by the app"


def test_unsaved_hook_file_newer_than_commit_is_refused_and_both_times_named(env, capsys):
    """Row 3: a differing `hooks/register.tsx`, newer than the last commit, bytes in no commit -> refused as
    today, and the line carries the install mtime and the last commit time."""
    repo, inst = env
    commit_ts = int(_git(repo, "log", "-1", "--format=%ct", capture=True))
    install_ts = commit_ts + 3600
    (inst / "hooks" / "register.tsx").write_bytes(b"hand edit")
    os.utime(inst / "hooks" / "register.tsx", (install_ts, install_ts))
    assert mods.run_install("unslop") == 1
    out = capsys.readouterr().out
    assert "refused" in out and "hooks/register.tsx" in out
    assert _iso(install_ts) in out
    assert _iso(commit_ts) in out
    assert (inst / "hooks" / "register.tsx").read_bytes() == b"hand edit"
